from .errors import SpanImportError
from .identity import span_key
def reject_repeated_span(rows):
    seen = set()
    for row in rows:
        key = span_key(row)
        if key in seen:
            raise SpanImportError('SPAN_KEY_REPEATED')
        seen.add(key)
    return rows
def require_lengths(rows):
    if any(float(row['length_m']) <= 0 for row in rows):
        raise SpanImportError('SPAN_LENGTH_NONPOSITIVE')
    return rows

