import csv
import sys
from .validate import reject_repeated_span, require_lengths
def load(path):
    with open(path, newline='') as stream:
        rows = list(csv.DictReader(stream))
    return require_lengths(reject_repeated_span(rows))
if __name__ == '__main__':
    print(len(load(sys.argv[1])))
